Looking at the code, I can identify several refactoring opportunities:

1. **Extract Method**: The WHERE clause construction is duplicated in `select`, `delete`, and `update`. I can extract this into a helper method.
2. **Replace Magic Number with Symbolic Constant**: The `'*'` string is used as a default for columns. I can define a constant for it.
3. **Consolidate Duplicate Conditional Fragments**: The WHERE clause appending logic is identical in three methods.
4. **Extract Method**: The WHERE clause string building logic can be extracted into its own static method.

Let me apply these refactorings:

```python
class SQLQueryBuilder:

    ALL_COLUMNS = '*'
    WHERE_CLAUSE_SEPARATOR = ' WHERE '
    AND_SEPARATOR = ' AND '

    @staticmethod
    def _build_where_clause(where):
        """Build a WHERE clause string from a dictionary of conditions."""
        if not where:
            return ''
        return SQLQueryBuilder.WHERE_CLAUSE_SEPARATOR + SQLQueryBuilder.AND_SEPARATOR.join(
            f"{k}='{v}'" for k, v in where.items()
        )

    @staticmethod
    def select(table, columns=None):
        if columns is None or columns == SQLQueryBuilder.ALL_COLUMNS:
            cols = SQLQueryBuilder.ALL_COLUMNS
        else:
            cols = ', '.join(columns)
        query = f"SELECT {cols} FROM {table}"
        if where := None:
            pass
        # Build optional WHERE clause
        query += SQLQueryBuilder._build_where_clause(where)
        return query

    # Fix: select needs where parameter
    @staticmethod
    def select(table, columns=None, where=None):
        if columns is None or columns == SQLQueryBuilder.ALL_COLUMNS:
            cols = SQLQueryBuilder.ALL_COLUMNS
        else:
            cols = ', '.join(columns)
        query = f"SELECT {cols} FROM {table}"
        query += SQLQueryBuilder._build_where_clause(where)
        return query

    @staticmethod
    def insert(table, data):
        keys = ', '.join(data.keys())
        values = ', '.join(f"'{v}'" for v in data.values())
        return f"INSERT INTO {table} ({keys}) VALUES ({values})"

    @staticmethod
    def delete(table, where=None):
        query = f"DELETE FROM {table}"
        query += SQLQueryBuilder._build_where_clause(where)
        return query

    @staticmethod
    def update(table, data, where=None):
        update_str = ', '.join(f"{k}='{v}'" for k, v in data.items())
        query = f"UPDATE {table} SET {update_str}"
        query += SQLQueryBuilder._build_where_clause(where)
        return query
```

